import React, {useEffect, useState} from "react";
import {toast} from "react-toastify";
import {Alert, Button, CircularProgress, Stack, TextField, Typography} from "@mui/material";
import {Link, useNavigate, useParams} from "react-router-dom";
import {getActiveFirmId} from "../../api/config";
import {getApiErrorMessage} from "../../api/errors";
import {useAuth} from "../../auth/AuthContext";
import {ReceiptApprovalStatus} from "../../models/transportWaybill";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {approvalLabel, useApproveGoodsInvoiceMutation, useGoodsInvoiceQuery, useInvoicePreparationQuery} from "../transportWaybills/goodsInvoicesApi";
import OriginalInvoicePreview from "../transportWaybills/OriginalInvoicePreview";
import {applySuggestedProducts, Draft, Row, waybillPayload, waybillRows} from "./WaybillReceiptPage";
import {newRequestId} from "./receiptDraft";
import InvoiceProductRows from "./InvoiceProductRows";
import DocumentCounterparties from '../counterparties/DocumentCounterparties';
import {ReceiptPricingTerms} from "./warehouseReceiptsApi";

type ApprovalDraft = Draft & {expectedVersion: string; comment?: string; pricing?: ReceiptPricingTerms};
export default function InvoiceApprovalPage() {
    const id = Number(useParams().id); const {user} = useAuth();
    return <Editor key={`${getActiveFirmId()}.${user?.id}.${id}`} id={id}/>;
}
function Editor({id}: {id: number}) {
    const {user,isCompanyAdmin,isSuperAdmin} = useAuth(); const canReview = isCompanyAdmin || isSuperAdmin; const navigate = useNavigate();
    const validId = Number.isInteger(id) && id > 0;
    const invoice = useGoodsInvoiceQuery(id,{skip:!validId,pollingInterval:15000});
    const preparation = useInvoicePreparationQuery(id,{skip:!validId});
    const storageKey = `vivotech.invoice-approval.${getActiveFirmId()}.${user?.id}.${id}`;
    const [draft,setDraft] = useState<ApprovalDraft | null>(() => {try {const saved = JSON.parse(sessionStorage.getItem(storageKey) || "null");return saved?.requestId && saved?.expectedVersion && Array.isArray(saved.rows) ? saved : null;} catch {return null;}});
    const [error,setError] = useState("");
    const [approve,approveState] = useApproveGoodsInvoiceMutation();
    const busy = approveState.isLoading;
    useEffect(() => {
        const prepared = preparation.data; const expectedVersion = invoice.data?.approvalVersion;
        const item = invoice.data;
        const pricing = item?.priceCurrency ? {currency:item.priceCurrency, fxRate:item.priceFxRate ?? null, fxDate:new Date().toISOString().slice(0,10), fxSource:"Указан при загрузке файла для прихода", warehouse:"Основной склад"} : undefined;
        if (expectedVersion && prepared) setDraft(current => current ? {...applySuggestedProducts(current, prepared), expectedVersion: current.expectedVersion || expectedVersion, pricing: current.pricing ?? pricing} : {requestId:newRequestId(),rows:waybillRows(prepared),submitted:false,expectedVersion,pricing});
    },[invoice.data,preparation.data]);
    useEffect(() => {if (draft) sessionStorage.setItem(storageKey,JSON.stringify(draft));},[storageKey,draft]);
    const change = (sourceId: number, update: Partial<Row>) => setDraft(current => current && !current.submitted ? {...current,rows:current.rows.map(row => row.sourceId === sourceId ? {...row,...update} : row)} : current);
    const save = async () => {
        if (!draft || !canReview || invoice.data?.isArchived || draft.expectedVersion !== invoice.data?.approvalVersion) return;
        const receipt = waybillPayload(id,draft);
        if (!receipt) {setError("Для каждой принятой строки выберите товар и положительное количество в складских единицах. Остальные строки исключите.");return;}
        receipt.comment = draft.comment?.trim() || `Приход по файлу #${id}`;
        if (draft.pricing) receipt.pricing = draft.pricing;
        const pending = {...draft,submitted:true}; setDraft(pending); setError("");
        try {await approve({id,expectedVersion:draft.expectedVersion,receipt}).unwrap();sessionStorage.removeItem(storageKey);toast.success("Товары добавлены на склад. Файл для прихода сохранён в архиве.");navigate("/stockManagement",{replace:true});}
        catch (failure) {
            const status = (failure as {status?: unknown}).status;
            if (typeof status === "number" && status >= 400 && status < 500) {
                const refreshed = await invoice.refetch();
                if (refreshed.data?.approvedReceiptId) {sessionStorage.removeItem(storageKey);navigate(`/invoices/receipts/${refreshed.data.approvedReceiptId}`,{replace:true});return;}
                setDraft({...pending,submitted:false});
            }
            setError(getApiErrorMessage(failure,"Ответ сервера не получен. Повторите одобрение: состав и номер прихода сохранены."));
        }
    };
    if (invoice.isLoading || preparation.isLoading) return <MainDiv><CircularProgress/></MainDiv>;
    if (invoice.isError || !invoice.data) return <MainDiv><Alert severity="error">Файл для прихода недоступен.</Alert><Button component={Link} to="/warehouseApprovals">К согласованию приходов</Button></MainDiv>;
    const item = invoice.data;
    const staleDraft = !!draft && draft.expectedVersion !== item.approvalVersion;
    const pending = !item.isArchived && !staleDraft && item.approvalStatus === ReceiptApprovalStatus.Pending;
    const receiptId = item.approvedReceiptId || preparation.data?.receiptId;
    const locked = busy || !!draft?.submitted;
    const rows = draft && preparation.data ? applySuggestedProducts(draft,preparation.data).rows : draft?.rows || [];
    return <MainDiv><Stack spacing={2}><PageTitle>Приёмка по файлу {item.number || `#${id}`}</PageTitle>
        <Stack direction="row" gap={1} flexWrap="wrap"><Button component={Link} to="/invoices">Файлы для прихода</Button><Button component={Link} to="/invoices?archive=Archived">Архив файлов для прихода</Button></Stack>
        <Alert severity={item.approvalStatus === ReceiptApprovalStatus.Rejected ? "warning" : item.approvalStatus === ReceiptApprovalStatus.Approved ? "success" : "info"}>{approvalLabel(item.approvalStatus)}{pending && ". Остатки по этому предложению ещё не увеличены."}</Alert>
        {item.isArchived && <Alert severity="info">{item.approvalStatus === ReceiptApprovalStatus.Approved ? "Файл для прихода в архиве. Приход одобрен; оригинал доступен для просмотра и скачивания." : "Файл для прихода в архиве. Для согласования восстановите его в списке файлов для прихода."}</Alert>}
        {!item.isArchived && staleDraft && item.approvalStatus === ReceiptApprovalStatus.Pending && <Alert severity="warning">
            Файл для прихода изменился. Обновите предложение и сверьте строки заново.
            <Button disabled={!preparation.data} onClick={() => {if (preparation.data && item.approvalVersion) setDraft({requestId:newRequestId(),rows:waybillRows(preparation.data),submitted:false,expectedVersion:item.approvalVersion,comment:draft?.comment});}}>Обновить предложение</Button>
        </Alert>}
        {item.reviewedAt && <Typography>Решение: {new Date(item.reviewedAt).toLocaleString("ru-RU")} · администратор #{item.reviewedByUserId}</Typography>}
        {item.rejectionReason && <Typography>Причина отклонения: {item.rejectionReason}</Typography>}
        <OriginalInvoicePreview id={id}/>
        <DocumentCounterparties document={item} onSaved={version => {void invoice.refetch(); void preparation.refetch(); setDraft(current => current ? {...current, expectedVersion: version, submitted: false} : current);}}/>
        {receiptId && <Alert severity="success">Приход по этому файлу уже сохранён. <Button component={Link} to={`/invoices/receipts/${receiptId}`}>Открыть приёмку</Button></Alert>}
        {error && <Alert severity="error">{error}</Alert>}
        {item.priceKind != null && item.priceKind !== 3 && <Alert severity={item.approvalStatus === ReceiptApprovalStatus.Approved ? "info" : "warning"}>{item.approvalStatus === ReceiptApprovalStatus.Approved ? "При одобрении была перезаписана" : "При одобрении будет перезаписана"} {item.priceKind === 0 ? "закупочная цена" : item.priceKind === 1 ? "себестоимость" : "конечная цена"} выбранных товаров. Валюта файла: {item.priceCurrency}; курс: {item.priceFxRate} BYN за единицу. Строки без распознанной цены сохраняют прежнее значение. Остальные виды цен сохраняются.</Alert>}
        {item.priceKind === 3 && <Alert severity="info">При загрузке выбран файл без цен. Будут приняты товары и количество; цены карточек сохранятся.</Alert>}
        {item.priceKind == null && <Alert severity="info">Вид цены не выбран при загрузке. Приход изменит остатки; цены карточек по этому файлу сохранятся.</Alert>}
        {pending && !canReview && <Alert severity="info">Предложение отправлено администратору компании. Только администратор может принять решение.</Alert>}
        {preparation.isError && <Alert severity="error">Не удалось подготовить строки для приёмки. Проверьте распознавание и обновите страницу.</Alert>}
        {pending && draft && !receiptId && <>
            <Typography color="text.secondary">Проверьте товары и количество, затем нажмите «Одобрить».</Typography>
            {canReview && <Stack direction={{xs: "column", md: "row"}} gap={1}>
                {([['currency', 'Валюта закупки'], ['fxRate', 'Курс BYN за 1 ед. валюты'], ['fxDate', 'Дата курса'], ['fxSource', 'Источник курса'], ['warehouse', 'Склад']] as const).filter(([key]) => item.priceKind !== 3 || key === 'warehouse').map(([key, label]) => {
                    const pricing = draft.pricing || {currency: "BYN", fxRate: 1, fxDate: new Date().toISOString().slice(0, 10), fxSource: "Подтверждённый документ BYN", warehouse: "Основной склад"};
                    return <TextField key={key} size="small" label={key === "currency" ? "Валюта файла" : label} value={pricing[key] ?? ""} disabled={locked || (item.priceKind != null && (key === "currency" || key === "fxRate"))} type={key === "fxRate" ? "number" : key === "fxDate" ? "date" : "text"} InputLabelProps={{shrink: true}}
                        onChange={e => setDraft(d => d && !d.submitted ? {...d, pricing: {...pricing, [key]: key === "fxRate" ? e.target.value === "" ? null : Number(e.target.value) : key === "currency" ? e.target.value.toUpperCase() : e.target.value,
                            ...(key === "currency" ? {fxRate: e.target.value.toUpperCase() === "BYN" ? 1 : null, fxSource: e.target.value.toUpperCase() === "BYN" ? "Подтверждённый документ BYN" : ""} : {})}} : d)}/>;
                })}
            </Stack>}
            {draft.submitted && <Alert severity="warning">Предложение отправлено. Состав зафиксирован; повтор использует тот же номер прихода.</Alert>}
            <InvoiceProductRows rows={rows} disabled={locked} canReview={canReview} onChange={change}
                showPrice={item.priceKind !== 3}
                priceLabel={item.priceKind === 1 ? "Себестоимость" : item.priceKind === 2 ? "Конечная цена" : item.priceKind === 0 ? "Закупочная цена" : "Цена из файла"} currency={item.priceCurrency || "BYN"} fxRate={item.priceKind != null && item.priceKind !== 3 ? item.priceFxRate : undefined}
                sourceLines={(preparation.data?.lines || []).map(line => {const source = item.lineItems?.find(source => source.id === line.id); return {id:line.id,gtin:line.gtin,unitPrice:source?.unitPrice ?? (source?.amountWithoutVat != null && source.quantity && source.quantity > 0 ? source.amountWithoutVat / source.quantity : null)};})}/>
            {canReview && <Button variant="contained" disabled={busy || !rows.some(row => row.included)} onClick={() => void save()}>{approveState.isLoading ? "Добавляем на склад…" : draft.submitted ? "Повторить одобрение" : "Одобрить"}</Button>}
        </>}
    </Stack></MainDiv>;
}
