import React, {useRef, useState} from "react";
import {Alert, Button, CircularProgress, Stack, TextField, Typography} from "@mui/material";
import {Link} from "react-router-dom";
import {getApiErrorMessage} from "../../api/errors";
import {CategoryType} from "../../models/category";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import {useCreateProductMutation} from "../products/productsApi";
import {StockLookup} from "./warehouseReceiptsApi";

type Props = {
    name: string;
    gtin?: string | null;
    unitPrice?: number | null;
    onCreated: (product: StockLookup) => void;
    onCancel: () => void;
    onBusyChange: (busy: boolean) => void;
};

function normalizeGtin(value: string): string | null {
    const digits = value.trim();
    if (!/^(?:\d{8}|\d{12}|\d{13}|\d{14})$/.test(digits)) return null;
    const sum = Array.from(digits.slice(0, -1)).reverse().reduce((total, digit, index) => total + Number(digit) * (index % 2 === 0 ? 3 : 1), 0);
    return (10 - sum % 10) % 10 === Number(digits.slice(-1)) ? digits.padStart(14, "0") : null;
}

export default function CreateInvoiceProductForm({name, gtin, unitPrice, onCreated, onCancel, onBusyChange}: Props) {
    const categories = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const [createProduct, state] = useCreateProductMutation();
    const saving = useRef(false);
    const [values, setValues] = useState({name, gtin: gtin || "", description: name, price: unitPrice == null ? "" : String(unitPrice), categoryId: ""});
    const [error, setError] = useState("");
    const change = (key: keyof typeof values, value: string) => setValues(current => ({...current, [key]: value}));
    const save = async (event: React.FormEvent) => {
        event.preventDefault();
        if (saving.current) return;
        const normalizedGtin = values.gtin.trim() ? normalizeGtin(values.gtin) : "";
        const priceText = values.price.trim().replace(",", ".");
        const price = Number(priceText);
        if (values.name.trim().length < 2 || values.name.trim().length > 1000 || !categories.data?.some(category => String(category.id) === values.categoryId)) {
            setError("Укажите название от 2 до 1000 символов и выберите категорию товара.");
            return;
        }
        if (normalizedGtin === null) {
            setError("Проверьте GTIN: 8, 12, 13 или 14 цифр с правильной контрольной цифрой. Если кода нет в документе, оставьте поле пустым.");
            return;
        }
        if (priceText && (!/^\d+(?:\.\d+)?$/.test(priceText) || !Number.isFinite(price) || price < 0 || price > 1e12)) {
            setError("Укажите цену от 0 до 1 000 000 000 000.");
            return;
        }
        const body = new FormData();
        body.append("name", values.name.trim());
        body.append("gtin", normalizedGtin);
        body.append("description", values.description.trim());
        if (priceText) body.append("price", String(price));
        body.append("categoryId", values.categoryId);
        body.append("characteristics", "[]");
        body.append("fields", "{}");
        saving.current = true;
        onBusyChange(true);
        setError("");
        try {
            const productId = await createProduct(body).unwrap();
            onCreated({productId, gtin: normalizedGtin, name: values.name.trim(), currentStock: 0});
        } catch (failure) {
            setError(getApiErrorMessage(failure, "Не удалось создать товар. Проверьте каталог и повторите сохранение."));
        } finally {
            saving.current = false;
            onBusyChange(false);
        }
    };
    return <Stack component="form" onSubmit={event => void save(event)} spacing={2} sx={{pt: 1}}>
        <Typography fontWeight={700}>Новый товар из файла для прихода</Typography>
        <Typography color="text.secondary">Проверьте данные. Товар будет добавлен в каталог CRM; количество поступит на склад после одобрения прихода.</Typography>
        {error && <Alert severity="error">{error}</Alert>}
        {categories.isLoading && <CircularProgress size={24}/>}
        {categories.isError && <Alert severity="error">Не удалось загрузить категории. <Button onClick={() => void categories.refetch()}>Повторить загрузку категорий</Button></Alert>}
        {categories.data?.length === 0 && <Alert severity="warning">Сначала добавьте категорию товаров. <Button component={Link} to="/categoriesManagement" target="_blank" rel="noopener noreferrer">Открыть категории</Button><Button onClick={() => void categories.refetch()}>Обновить категории</Button></Alert>}
        <TextField label="Название нового товара" value={values.name} disabled={state.isLoading} onChange={event => change("name", event.target.value)}/>
        <TextField label="GTIN нового товара" value={values.gtin} disabled={state.isLoading} inputProps={{inputMode: "numeric"}} helperText="Необязательно. Если штрихкода нет, товар будет принят по выбранной карточке каталога." onChange={event => change("gtin", event.target.value)}/>
        <TextField label="Категория нового товара" select SelectProps={{native: true}} InputLabelProps={{shrink: true}} value={values.categoryId} disabled={state.isLoading || !categories.data?.length} onChange={event => change("categoryId", event.target.value)}>
            <option value="">Выберите категорию</option>
            {categories.data?.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}
        </TextField>
        <TextField label="Описание нового товара" multiline value={values.description} disabled={state.isLoading} onChange={event => change("description", event.target.value)}/>
        <TextField label="Цена нового товара" value={values.price} disabled={state.isLoading} inputProps={{inputMode: "decimal"}} helperText="Конечная цена в BYN, необязательно. Цена файла будет применена при одобрении прихода. До заполнения всех цен карточка неактивна для заказов." onChange={event => change("price", event.target.value)}/>
        <Stack direction="row" gap={1} flexWrap="wrap">
            <Button type="submit" variant="contained" disabled={state.isLoading || !categories.data?.length}>{state.isLoading ? "Создаём товар…" : "Создать товар и добавить в каталог"}</Button>
            <Button disabled={state.isLoading} onClick={onCancel}>Отмена создания</Button>
        </Stack>
    </Stack>;
}
