import React, {useEffect, useState} from "react";
import {toast} from "react-toastify";
import {Alert, Autocomplete, Button, Checkbox, CircularProgress, FormControlLabel, Paper, Stack, TextField, Typography} from "@mui/material";
import {Link, useNavigate, useParams} from "react-router-dom";
import {getActiveFirmId} from "../../api/config";
import {getApiErrorMessage} from "../../api/errors";
import {useAuth} from "../../auth/AuthContext";
import useDebounce from "../../hooks/useDebounce";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {newRequestId, positiveQuantity} from "./receiptDraft";
import {ReceiveStock, StockLookup, useReceiveStockMutation, useSearchStockQuery, useWaybillReceiptPreparationQuery, WaybillReceiptPreparation} from "./warehouseReceiptsApi";

export type Row = {sourceId: number; name: string; originalQuantity: number | null; unit: string; included: boolean; product: StockLookup | null; quantity: string; quantityChanged?: boolean; productSelectionChanged?: boolean; baseUnit?: string; unitsPerPurchaseUnit?: string};
export type Draft = {requestId: string; rows: Row[]; submitted: boolean};
export function waybillRows(document: WaybillReceiptPreparation): Row[] {
    return document.lines.map(line => ({sourceId:line.id, name:line.name || `Строка ${line.rowNumber}`, originalQuantity:line.quantity, unit:line.unitName || "единица не распознана", included:true,
        product:line.suggestedProduct, quantity:line.quantity !== null && positiveQuantity(String(line.quantity)) !== null ? String(line.quantity) : ""}));
}
export function applySuggestedProducts<T extends Draft>(draft: T, document: WaybillReceiptPreparation): T {
    if (draft.submitted) return draft;
    const suggestions = new Map(document.lines.map(line => [line.id, line.suggestedProduct]));
    let changed = false;
    const rows = draft.rows.map(row => {
        const product = suggestions.get(row.sourceId);
        if (!row.included || row.product || row.productSelectionChanged || !product) return row;
        changed = true;
        return {...row, product, quantity:row.quantity || (!row.quantityChanged && row.originalQuantity !== null && positiveQuantity(String(row.originalQuantity)) !== null ? String(row.originalQuantity) : "")};
    });
    return changed ? {...draft, rows} : draft;
}
export function waybillPayload(id: number, draft: Draft): ReceiveStock | null {
    const rows = draft.rows.filter(row => row.included);
    if (!rows.length || rows.some(row => !row.product || positiveQuantity(row.quantity) === null || (row.unitsPerPurchaseUnit !== undefined && (positiveQuantity(row.unitsPerPurchaseUnit) === null || !row.baseUnit?.trim())))) return null;
    return {requestId:draft.requestId, transportWaybillId:id, comment:`Приход по накладной #${id}`, excludedSourceLineIds:draft.rows.filter(row => !row.included).map(row => row.sourceId),
        lines:rows.map(row => ({gtin:row.product!.gtin, ...(row.product!.gtin ? {} : {productId:row.product!.productId}), quantity:positiveQuantity(row.quantity)!, sourceLineId:row.sourceId,
            ...(row.baseUnit || row.unitsPerPurchaseUnit ? {baseUnit: row.baseUnit?.trim() || row.unit, unitsPerPurchaseUnit: positiveQuantity(row.unitsPerPurchaseUnit || "1")!} : {})}))};
}

export function ProductPicker({row, disabled, onChange}: {row: Row; disabled: boolean; onChange: (product: StockLookup | null) => void}) {
    const [query, setQuery] = useState(row.product?.name || row.name.slice(0,100));
    const term = useDebounce(query);
    const search = useSearchStockQuery(term, {skip:term.trim().length < 2 || disabled});
    const options = [...(row.product ? [row.product] : []), ...(search.data || []).filter(product => product.productId !== row.product?.productId)];
    return <Autocomplete value={row.product} options={options} disabled={disabled} loading={search.isFetching} filterOptions={items => items}
        isOptionEqualToValue={(a,b) => a.productId === b.productId} getOptionLabel={product => product.gtin ? `${product.name} · ${product.gtin}` : product.name}
        onInputChange={(_,value,reason) => {if (reason === "input" || reason === "clear") setQuery(value);}} onChange={(_,value) => onChange(value)}
        noOptionsText={search.isError ? "Ошибка поиска. Повторите ввод." : term.trim().length < 2 ? "Введите минимум 2 символа" : "Товары не найдены. Проверьте название или GTIN в карточке товара."}
        loadingText="Загрузка товаров…"
        renderInput={params => <TextField {...params} label="Товар CRM: название или GTIN" helperText="Выберите товар по названию или GTIN."/>}/>;
}

export default function WaybillReceiptPage() {
    const id = Number(useParams().waybillId); const {user} = useAuth();
    return <WaybillReceiptEditor key={`${getActiveFirmId()}.${user?.id}.${id}`} id={id}/>;
}
function WaybillReceiptEditor({id}: {id: number}) {
    const {user} = useAuth(); const navigate = useNavigate();
    const storageKey = `vivotech.waybill-receipt.${getActiveFirmId()}.${user?.id}.${id}`;
    const document = useWaybillReceiptPreparationQuery(id, {skip:!Number.isInteger(id) || id <= 0});
    const [draft, setDraft] = useState<Draft | null>(() => {try {const saved = JSON.parse(sessionStorage.getItem(storageKey) || "null"); return saved?.requestId && Array.isArray(saved.rows) ? saved : null;} catch {return null;}});
    const [error, setError] = useState(""); const [receive, state] = useReceiveStockMutation();
    useEffect(() => {
        const prepared = document.data;
        if (prepared) setDraft(current => current ? applySuggestedProducts(current, prepared) : {requestId:newRequestId(), rows:waybillRows(prepared), submitted:false});
    }, [document.data]);
    useEffect(() => {if (draft) sessionStorage.setItem(storageKey, JSON.stringify(draft));}, [storageKey, draft]);
    const change = (sourceId: number, update: Partial<Row>) => setDraft(current => current && !current.submitted ? {...current, rows:current.rows.map(row => row.sourceId === sourceId ? {...row,...update} : row)} : current);
    const save = async () => {
        if (!draft) return; const payload = waybillPayload(id,draft);
        if (!payload) {setError("Для каждой принятой строки выберите товар и укажите положительное количество в складских единицах."); return;}
        setError(""); const pending = {...draft,submitted:true}; setDraft(pending);
        try {const receipt = await receive(payload).unwrap(); sessionStorage.removeItem(storageKey); toast.success("Приход по ТТН сохранён. Остатки обновлены."); navigate(`/invoices/receipts/${receipt.id}`,{replace:true});}
        catch (failure) {
            const status = (failure as {status?: unknown}).status;
            if (typeof status === "number" && status >= 400 && status < 500) {
                const refreshed = await document.refetch();
                if (refreshed.data?.receiptId) {sessionStorage.removeItem(storageKey); navigate(`/invoices/receipts/${refreshed.data.receiptId}`,{replace:true}); return;}
                setDraft({...pending,submitted:false});
            }
            setError(getApiErrorMessage(failure,"Ответ сервера не получен. Повторите сохранение — номер и состав прихода сохранены."));
        }
    };
    if (document.isLoading) return <MainDiv><CircularProgress/></MainDiv>;
    if (document.isError || !document.data || !draft) return <MainDiv><Alert severity="error">{getApiErrorMessage(document.error,"ТТН недоступна для приёмки.")}</Alert><Button component={Link} to="/transportWaybills">К накладным</Button></MainDiv>;
    if (document.data.receiptId) return <MainDiv><Alert severity="success">Приход по этой загрузке ТТН уже проведён.</Alert><Button component={Link} to={`/invoices/receipts/${document.data.receiptId}`}>Открыть приёмку</Button></MainDiv>;
    return <MainDiv><Stack spacing={2}><PageTitle>Приход по ТТН {document.data.number || `#${id}`}</PageTitle>
        <Typography>Проверьте товары и количество, затем подтвердите приход.</Typography>
        {error && <Alert severity="error">{error}</Alert>}{draft.submitted && <Alert severity="warning">Состав зафиксирован после отправки. Повтор использует тот же номер прихода.</Alert>}
        {draft.rows.map(row => <Paper key={row.sourceId} variant="outlined" sx={{p:2}}><Stack spacing={1}>
            <FormControlLabel label={row.name} control={<Checkbox checked={row.included} disabled={draft.submitted} onChange={event => change(row.sourceId,{included:event.target.checked})}/>}/>
            <Typography color="text.secondary">В документе: {row.originalQuantity ?? "не распознано"} {row.unit}</Typography>
            <ProductPicker row={row} disabled={draft.submitted || !row.included} onChange={product => change(row.sourceId,{product,productSelectionChanged:true})}/>
            {row.product && <Typography>Сейчас на складе: {row.product.currentStock} · GTIN {row.product.gtin}</Typography>}
            <TextField label="Количество в складских единицах" inputProps={{inputMode:"decimal"}} value={row.quantity} disabled={draft.submitted || !row.included} onChange={event => change(row.sourceId,{quantity:event.target.value})}/>
        </Stack></Paper>)}
        <Stack direction="row" gap={1}><Button variant="contained" disabled={state.isLoading} onClick={() => void save()}>{state.isLoading ? "Проводим приход…" : draft.submitted ? "Повторить сохранение" : "Подтвердить приход по ТТН"}</Button><Button component={Link} to="/catalogGeneration/file">Создать карточку из ePass</Button></Stack>
    </Stack></MainDiv>;
}
