import React, {useState} from "react";
import {toast} from "react-toastify";
import {Alert, Button, Checkbox, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, Paper, Stack, TextField, Typography} from "@mui/material";
import {ProductPicker, Row} from "./WaybillReceiptPage";
import {StockLookup} from "./warehouseReceiptsApi";
import CreateInvoiceProductForm from "./CreateInvoiceProductForm";
import {positiveQuantity} from "./receiptDraft";

type Props = {
    rows: Row[];
    sourceLines: {id: number; gtin?: string | null; unitPrice?: number | null}[];
    disabled: boolean;
    canReview: boolean;
    onChange: (sourceId: number, update: Partial<Row>) => void;
    priceLabel?: string;
    currency?: string;
    fxRate?: number | null;
    showPrice?: boolean;
};

export default function InvoiceProductRows({rows, sourceLines, disabled, canReview, onChange, priceLabel = "Цена из файла", currency = "BYN", fxRate, showPrice = true}: Props) {
    const found = rows.filter(row => row.product);
    const missing = rows.filter(row => !row.product);
    const unresolvedCount = missing.filter(row => row.included).length;
    const [open, setOpen] = useState(unresolvedCount > 0);
    const [creatingId, setCreatingId] = useState<number | null>(null);
    const [creating, setCreating] = useState(false);
    const [editingId, setEditingId] = useState<number | null>(null);
    const locked = disabled || creating;
    const created = (row: Row, product: StockLookup) => {
        onChange(row.sourceId, {product, productSelectionChanged: true});
        setCreatingId(null);
        toast.success("Товар создан, добавлен в каталог и выбран для прихода.");
    };
    const renderRow = (row: Row, allowCreate: boolean) => {
        const price = sourceLines.find(line => line.id === row.sourceId)?.unitPrice;
        const factor = positiveQuantity(String(row.unitsPerPurchaseUnit ?? "1"));
        const quantity = positiveQuantity(String(row.quantity));
        return <Paper key={row.sourceId} variant="outlined" sx={{p: 2}}><Stack spacing={1}>
        {showPrice && <Typography fontWeight={600}>{priceLabel}: {sourceLines.find(line => line.id === row.sourceId)?.unitPrice ?? "Не распознана"} {currency} за единицу файла</Typography>}
        <Stack direction={{xs: "column", sm: "row"}} spacing={1} alignItems={{sm: "center"}}>
            <FormControlLabel sx={{flex: 1}} label={row.product?.name || row.name} control={<Checkbox checked={row.included} disabled={locked || !canReview} onChange={event => onChange(row.sourceId, {included: event.target.checked})}/>}/>
            <TextField size="small" label="Количество для прихода" inputProps={{inputMode: "decimal"}} value={row.quantity} disabled={locked || !row.included || !canReview} error={row.included && positiveQuantity(String(row.quantity)) == null} helperText={row.included && positiveQuantity(String(row.quantity)) == null ? "Введите количество больше 0, до 6 знаков после запятой" : "В единицах файла"} onChange={event => onChange(row.sourceId, {quantity: event.target.value, quantityChanged: true})}/>
        </Stack>
        {row.included && factor && quantity && <Typography variant="body2" color="text.secondary">На склад: {(quantity * factor).toLocaleString("ru-RU", {maximumFractionDigits: 6})} {row.baseUnit || row.unit || "ед."}.</Typography>}
        {row.included && price != null && fxRate && factor && <Typography variant="body2" fontWeight={600}>{priceLabel} для карточки: {(price * fxRate / factor).toLocaleString("ru-RU", {maximumFractionDigits: 6})} BYN за {row.baseUnit || row.unit || "базовую единицу"}.</Typography>}
        <Stack direction={{xs: "column", sm: "row"}} spacing={1}>
            <TextField size="small" label="Базовая единица склада и цены" value={row.baseUnit ?? row.unit} disabled={locked || !row.included || !canReview} onChange={e => onChange(row.sourceId, {baseUnit: e.target.value})}/>
            <TextField size="small" label="Базовых единиц в единице файла" value={row.unitsPerPurchaseUnit ?? "1"} disabled={locked || !row.included || !canReview} error={row.included && positiveQuantity(String(row.unitsPerPurchaseUnit ?? "1")) == null} inputProps={{inputMode: "decimal"}} onChange={e => onChange(row.sourceId, {unitsPerPurchaseUnit: e.target.value, baseUnit: row.baseUnit || row.unit})} helperText="Например: 100 м в бухте — укажите 100. Для штучного товара — 1."/>
        </Stack>
        {row.product && <Button size="small" sx={{alignSelf: "flex-start"}} disabled={locked || !canReview} onClick={() => setEditingId(editingId === row.sourceId ? null : row.sourceId)}>{editingId === row.sourceId ? "Скрыть выбор товара" : "Изменить товар"}</Button>}
        {(!row.product || editingId === row.sourceId) && <ProductPicker row={row} disabled={locked || !row.included} onChange={product => onChange(row.sourceId, {product, productSelectionChanged: true})}/>}
        {!row.included && <Typography color="text.secondary">Строка исключена из прихода.</Typography>}
        {allowCreate && creatingId !== row.sourceId && <Button variant="outlined" disabled={locked || !row.included} onClick={() => setCreatingId(row.sourceId)}>Создать товар в CRM</Button>}
        {allowCreate && creatingId === row.sourceId && <CreateInvoiceProductForm name={row.name} gtin={sourceLines.find(line => line.id === row.sourceId)?.gtin}
            onCreated={product => created(row, product)} onCancel={() => setCreatingId(null)} onBusyChange={setCreating}/>}
    </Stack></Paper>;
    };

    return <Stack spacing={2}>
        {!!missing.length && <Alert severity={unresolvedCount ? "warning" : "success"}>
            Найдено в каталоге: {found.length}. Не сопоставлено: {unresolvedCount}.
            {!!missing.length && <Button disabled={disabled} onClick={() => setOpen(true)}>Открыть ненайденные товары ({unresolvedCount})</Button>}
        </Alert>}
        <Typography variant="h6" component="h2">Товары ({found.length})</Typography>
        {found.length ? found.map(row => renderRow(row, false)) : <Typography color="text.secondary">Совпадений пока нет. Сопоставьте или создайте товары в отдельном окне.</Typography>}
        <Dialog open={open} fullWidth maxWidth="md" aria-labelledby="missing-invoice-products-title" onClose={() => {if (!locked) setOpen(false);}}>
            <DialogTitle id="missing-invoice-products-title">Ненайденные товары ({unresolvedCount})</DialogTitle>
            <DialogContent dividers><Stack spacing={2}>
                {unresolvedCount > 0 && <Alert severity="info">Эти строки не удалось однозначно сопоставить с товарами CRM по названию или GTIN. Проверьте поиск, выберите существующий товар или создайте новый. Сопоставленные строки появятся в отдельном списке.</Alert>}
                {unresolvedCount === 0 && <Alert severity="success">Все товары сопоставлены или исключены из прихода.</Alert>}
                {missing.map(row => renderRow(row, true))}
            </Stack></DialogContent>
            <DialogActions><Button disabled={locked} onClick={() => setOpen(false)}>Вернуться к файлу для прихода</Button></DialogActions>
        </Dialog>
    </Stack>;
}
